import{_ as e,o as a,c as o,ag as d}from"./chunks/framework.CxkNbRKf.js";const m=JSON.parse('{"title":"Key concepts","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/content/indicators-concepts.md","filePath":"admin-guide/content/indicators-concepts.md","lastUpdated":1793155456000}'),r={name:"admin-guide/content/indicators-concepts.md"};function s(n,t,i,c,h,l){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="key-concepts" tabindex="-1">Key concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key concepts&quot;">​</a></h1><p>This page explains the parts of an indicator in NADA and the words used throughout this guide. Read it before you create your first indicator.</p><p>The same example is used on every page: the World Bank indicator <strong>SI.POV.DDAY</strong>, <em>Poverty headcount ratio at $3.00 a day (2021 PPP) (% of population)</em>, for 183 countries from 1963 to 2025. The <a href="https://github.com/ihsn/nada-documentation/tree/main/examples/indicators" target="_blank" rel="noreferrer">sample files</a> contain its data, data structure and metadata.</p><p>For the overall workflow, see the <a href="./indicators.html">overview</a>.</p><hr><h2 id="indicator-and-time-series" tabindex="-1">Indicator and time series <a class="header-anchor" href="#indicator-and-time-series" aria-label="Permalink to &quot;Indicator and time series&quot;">​</a></h2><p>An <strong>indicator</strong> is a summary measure of something, such as a poverty rate or an infant mortality rate. It is usually produced from other data: a census, surveys, administrative records. SI.POV.DDAY, for example, is computed from household surveys.</p><p>When an indicator&#39;s values are given for several points in time (years, quarters, months…), they form a <strong>time series</strong>. NADA treats indicators and time series the same way, whether the series is regular (every year) or not (only the years a survey was run). SI.POV.DDAY is irregular: most countries have values only for the years they ran a household survey.</p><p>In NADA, each indicator is one <strong>catalog entry</strong>, of type <em>Time series</em>. It has:</p><ul><li><strong>metadata</strong>, which describes the indicator;</li><li><strong>data</strong>, which holds its values;</li><li>a <strong>data structure</strong>, which describes the columns of the data.</li></ul><h2 id="metadata-series-description-and-source-database" tabindex="-1">Metadata: series description and source database <a class="header-anchor" href="#metadata-series-description-and-source-database" aria-label="Permalink to &quot;Metadata: series description and source database&quot;">​</a></h2><p>The <strong>series description</strong> documents the indicator: its name, definition, unit of measure, periodicity, methodology, sources, geographic and time coverage, license, and more. For SI.POV.DDAY, the unit is <code>%</code>, the periodicity is <em>Annual</em> and the source is the World Bank&#39;s Poverty and Inequality Platform. The series description is shown on the <strong>Series description</strong> tab of the catalog page, and it is what catalog search finds.</p><p>Indicators often come from a larger <strong>source database</strong>. SI.POV.DDAY comes from the World Bank&#39;s <em>World Development Indicators</em> (WDI). The database can be documented once, as its own entry, and linked from each indicator that comes from it. It is shown on the indicator&#39;s page as extra information. It is not a separate search result.</p><p>Both use metadata schemas developed for indicators: one for the series, and one for the database.</p><h2 id="data-observations-in-long-format" tabindex="-1">Data: observations in long format <a class="header-anchor" href="#data-observations-in-long-format" aria-label="Permalink to &quot;Data: observations in long format&quot;">​</a></h2><p>The data of an indicator is a table of <strong>observations</strong>. Each row holds <strong>one value</strong>, and the other columns say exactly what that value is. These rows come from the sample data file:</p><table tabindex="0"><thead><tr><th>INDICATOR</th><th>INDICATOR_LABEL</th><th>REF_AREA</th><th>YEAR</th><th>VALUE</th></tr></thead><tbody><tr><td>SI.POV.DDAY</td><td>Poverty headcount ratio at $3.00 a day (2021 PPP) (% of population)</td><td>ALB</td><td>2012</td><td>1.8</td></tr><tr><td>SI.POV.DDAY</td><td>Poverty headcount ratio at $3.00 a day (2021 PPP) (% of population)</td><td>ALB</td><td>2014</td><td>3.7</td></tr><tr><td>SI.POV.DDAY</td><td>Poverty headcount ratio at $3.00 a day (2021 PPP) (% of population)</td><td>ARG</td><td>2012</td><td>1.3</td></tr><tr><td>SI.POV.DDAY</td><td>Poverty headcount ratio at $3.00 a day (2021 PPP) (% of population)</td><td>ARG</td><td>2014</td><td>1.1</td></tr></tbody></table><p>This layout is called <strong>long format</strong>: one value per row. The alternative, a spreadsheet with one row per country and one column per year, is called <strong>wide format</strong>. NADA only accepts long format, so reshape wide data before uploading it.</p><p>The data is stored in MongoDB, separately from the metadata. See <a href="/nada-documentation/installation-guide/installation-mongodb.html">MongoDB setup</a>.</p><h3 id="one-indicator-or-a-dimension" tabindex="-1">One indicator, or a dimension? <a class="header-anchor" href="#one-indicator-or-a-dimension" aria-label="Permalink to &quot;One indicator, or a dimension?&quot;">​</a></h3><p>The sample has one value for each country and year. Many indicators are also broken down further, for example by sex. There are two ways to publish such data:</p><ul><li><strong>As separate indicators</strong>: one indicator for the total, one for women and one for men, each with its own code. This is what WDI does.</li><li><strong>As one indicator with a dimension</strong>: a <code>SEX</code> column with the codes <code>_T</code> (total), <code>F</code> and <code>M</code>, added to the data structure as a <strong>dimension</strong>.</li></ul><p>Both work. Choose one design and use it consistently across your catalog.</p><h2 id="data-structure-dsd" tabindex="-1">Data structure (DSD) <a class="header-anchor" href="#data-structure-dsd" aria-label="Permalink to &quot;Data structure (DSD)&quot;">​</a></h2><p>A <strong>data structure definition</strong>, or <strong>DSD</strong>, describes the columns of the data: their names, labels, data types, and the <strong>role</strong> each column plays. NADA uses the roles to build the chart, the filters, the data table and the Data API.</p><p>The data structure of the sample, <code>WB_WDI_COUNTRY_YEAR_1.0</code>:</p><table tabindex="0"><thead><tr><th>Column</th><th>Role</th><th>Data type</th><th>Codelist</th></tr></thead><tbody><tr><td><code>INDICATOR</code></td><td>Indicator ID</td><td>string</td><td></td></tr><tr><td><code>INDICATOR_LABEL</code></td><td>Indicator name</td><td>string</td><td></td></tr><tr><td><code>REF_AREA</code></td><td>Geography</td><td>string</td><td>Countries (<code>WB_CL_REF_AREA_1.0</code>)</td></tr><tr><td><code>YEAR</code></td><td>Time period, format <code>YYYY</code></td><td>string</td><td></td></tr><tr><td><code>VALUE</code></td><td>Observation value</td><td>double</td><td></td></tr></tbody></table><p>The column names in the data file must match the column names of the data structure.</p><p>A data structure is created once and can be <strong>shared by many indicators</strong> that have the same columns. Nothing in this one is specific to poverty: any annual, country-level indicator from WDI could use it. Each indicator links to exactly one data structure.</p><div class="warning custom-block"><p class="custom-block-title">Changing a shared data structure</p><p>When a data structure changes, every indicator that uses it is marked <strong>sync pending</strong>, and its chart, table and Data API are hidden until it is resynced (the <strong>Resync</strong> button on its <strong>Indicator data</strong> tab) or its data is uploaded again. See <a href="./indicators.html#rules-that-apply-to-every-workflow">Rules that apply to every workflow</a>.</p></div><h3 id="column-roles" tabindex="-1">Column roles <a class="header-anchor" href="#column-roles" aria-label="Permalink to &quot;Column roles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Role</th><th>What the column holds</th><th>How many</th><th>Example</th></tr></thead><tbody><tr><td><strong>Indicator ID</strong></td><td>The code of the indicator</td><td>One (required)</td><td><code>INDICATOR</code>: <code>SI.POV.DDAY</code></td></tr><tr><td><strong>Indicator name</strong></td><td>The name of the indicator</td><td>At most one</td><td><code>INDICATOR_LABEL</code></td></tr><tr><td><strong>Geography</strong></td><td>The country or area code</td><td>At most one (recommended)</td><td><code>REF_AREA</code>: <code>ALB</code></td></tr><tr><td><strong>Time period</strong></td><td>When the value applies (see <a href="#time-period-formats">formats</a>)</td><td>One (required)</td><td><code>YEAR</code>: <code>2012</code></td></tr><tr><td><strong>Observation value</strong></td><td>The value itself</td><td>One (required)</td><td><code>VALUE</code>: <code>1.8</code></td></tr><tr><td><strong>Periodicity</strong></td><td>The frequency of the time period</td><td>At most one</td><td>A <code>FREQ</code> column: <code>A</code> (annual), <code>Q</code>, <code>M</code></td></tr><tr><td><strong>Dimension</strong></td><td>Any other breakdown of the value</td><td>Any number</td><td>A <code>SEX</code> column: <code>_T</code>, <code>F</code>, <code>M</code></td></tr><tr><td><strong>Measure</strong></td><td>Another measured value stored in the same row</td><td>Can be defined, but not yet supported for data (see below)</td><td></td></tr><tr><td><strong>Attribute</strong></td><td>Information about a value, which does not change what the value is</td><td>Any number</td><td>A status column: estimated, provisional</td></tr><tr><td><strong>Annotation</strong></td><td>A note about a value</td><td>Any number</td><td><em>Break in series</em></td></tr></tbody></table><p>The sample uses the first five roles. The others are shown with columns it does not have.</p><div class="info custom-block"><p class="custom-block-title">Measures</p><p>A data structure can define measure columns, including more than one. NADA and the Metadata Editor do not yet support measures in the data: uploads, charts and tables use the single observation value. Use one indicator per measured quantity for now.</p></div><h3 id="the-series-key" tabindex="-1">The series key <a class="header-anchor" href="#the-series-key" aria-label="Permalink to &quot;The series key&quot;">​</a></h3><p>The columns with the roles <strong>indicator ID, geography, dimension, periodicity and time period</strong> together identify a value. That combination is the <strong>series key</strong>, and it must be <strong>unique</strong>. In the sample, the key is <code>INDICATOR</code> + <code>REF_AREA</code> + <code>YEAR</code>, so the data cannot have two values for Albania in 2012.</p><p>Attributes, annotations and measures are not part of the key. They describe a value without changing what the value is.</p><h3 id="time-period-formats" tabindex="-1">Time period formats <a class="header-anchor" href="#time-period-formats" aria-label="Permalink to &quot;Time period formats&quot;">​</a></h3><p>The time period column uses one of these formats. Set the format on the time period column of the data structure. The sample uses <code>YYYY</code>.</p><table tabindex="0"><thead><tr><th>Format</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td><code>YYYY</code></td><td><code>2012</code></td><td>Year</td></tr><tr><td><code>YYYY-Sn</code></td><td><code>2012-S1</code></td><td>Half-year</td></tr><tr><td><code>YYYY-Qn</code></td><td><code>2012-Q3</code></td><td>Quarter</td></tr><tr><td><code>YYYY-MM</code></td><td><code>2012-07</code></td><td>Month</td></tr><tr><td><code>YYYY-Www</code></td><td><code>2012-W27</code></td><td>Week</td></tr><tr><td><code>YYYY-MM-DD</code></td><td><code>2012-07-01</code></td><td>Day</td></tr><tr><td><code>YYYY-MM-DDTHH:mm:ss</code></td><td><code>2012-07-01T12:00:00</code></td><td>Date and time (<code>Z</code> suffix for UTC)</td></tr></tbody></table><h3 id="identity-and-status" tabindex="-1">Identity and status <a class="header-anchor" href="#identity-and-status" aria-label="Permalink to &quot;Identity and status&quot;">​</a></h3><p>Each data structure is identified by an <strong>agency</strong> (the organization responsible), a <strong>name</strong> and a <strong>version</strong>, and gets an <strong>IDNO</strong>. The sample&#39;s data structure has agency <code>WB</code>, name <code>WDI_COUNTRY_YEAR</code>, version <code>1.0</code> and IDNO <code>WB_WDI_COUNTRY_YEAR_1.0</code>.</p><p>The indicator refers to its data structure by this IDNO, so the IDNO must stay the same in the Metadata Editor, in scripts and in NADA.</p><p>Data structures and codelists both have a <strong>status</strong>: <em>draft</em>, <em>review</em>, <em>published</em>, <em>deprecated</em> or <em>archived</em>.</p><h2 id="codelist" tabindex="-1">Codelist <a class="header-anchor" href="#codelist" aria-label="Permalink to &quot;Codelist&quot;">​</a></h2><p>A <strong>codelist</strong> is a list of codes and their labels. The sample&#39;s country codelist, <code>WB_CL_REF_AREA_1.0</code>, has the 183 countries in the data:</p><table tabindex="0"><thead><tr><th>Code</th><th>Label</th></tr></thead><tbody><tr><td><code>AGO</code></td><td>Angola</td></tr><tr><td><code>ALB</code></td><td>Albania</td></tr><tr><td><code>ARG</code></td><td>Argentina</td></tr><tr><td><code>ARM</code></td><td>Armenia</td></tr><tr><td>…</td><td>…</td></tr></tbody></table><p>Columns whose values are <strong>codes</strong> can use a codelist: geography, periodicity, dimensions, attributes and measures. The catalog then shows labels instead of codes in filters, charts and tables, and documents the codes on the <strong>Data structure</strong> tab.</p><p>These columns do not use a codelist:</p><ul><li><strong>Indicator ID and indicator name.</strong> Each indicator entry holds exactly one indicator, so the column has a single value. The indicator&#39;s name and description come from its metadata.</li><li><strong>Observation value, time period and annotation.</strong> They hold numbers, dates or free text.</li></ul><p>Like data structures, codelists are shared: one country codelist can serve every indicator in the catalog.</p><p>Make sure every code used in the data exists in the codelist. NADA does not check this when data is uploaded.</p><div class="tip custom-block"><p class="custom-block-title">Codelists from label columns</p><p>Data files often have a label column next to each code column (<code>REF_AREA_LABEL</code> next to <code>REF_AREA</code>, for example). The Metadata Editor can build the codelist from such pairs. NADA cannot: in NADA, import the codelist with the data structure, and leave label columns out of the data file.</p></div><p>Codelists can follow international standards. Importing an SDMX structure file (SDMX-ML 2.1, as published by OECD or Eurostat) creates the data structure and its codelists together, and reuses codelists that already exist.</p><hr><h2 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Attribute</strong></td><td>A column with information about a value (status, unit multiplier…). Not part of the series key.</td></tr><tr><td><strong>Catalog entry</strong></td><td>Any item listed in the NADA catalog. An indicator is an entry of type <em>Time series</em>.</td></tr><tr><td><strong>Codelist</strong></td><td>A list of codes and labels, used by a geography, periodicity, dimension, attribute or measure column.</td></tr><tr><td><strong>Component</strong></td><td>A column of a data structure. NADA screens use this word.</td></tr><tr><td><strong>Data structure (DSD)</strong></td><td>The definition of the data&#39;s columns, their roles and codelists. Shared by indicators with the same columns.</td></tr><tr><td><strong>Dimension</strong></td><td>A column that breaks values down (sex, age…). Part of the series key.</td></tr><tr><td><strong>IDNO</strong></td><td>The unique identifier of an entry, a data structure or a codelist.</td></tr><tr><td><strong>Indicator</strong></td><td>A summary measure published as a catalog entry, with metadata and data.</td></tr><tr><td><strong>Long format</strong></td><td>One value per row, with columns describing what the value is. Required by NADA.</td></tr><tr><td><strong>Observation</strong></td><td>One row of the data: one value and the columns that identify it.</td></tr><tr><td><strong>Series description</strong></td><td>The metadata that documents an indicator.</td></tr><tr><td><strong>Series key</strong></td><td>The combination of indicator ID, geography, dimensions, periodicity and time period that identifies a value. Must be unique.</td></tr><tr><td><strong>Source database</strong></td><td>A database that indicators come from, documented once and linked from each indicator.</td></tr><tr><td><strong>Sync pending</strong></td><td>The state of an indicator whose data structure changed (shown as <strong>Out of sync</strong> in the admin). Its data is hidden until it is resynced or uploaded again.</td></tr><tr><td><strong>Time series</strong></td><td>An indicator with values for several points in time.</td></tr></tbody></table><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./indicators.html">Overview</a>: choose a workflow</li><li><a href="/nada-documentation/admin-guide/web-ui/codelists.html">Codelists</a> and <a href="/nada-documentation/admin-guide/web-ui/data-structures.html">Data structures</a>: create them in NADA</li><li><a href="./indicators-tutorial.html">Tutorial</a>: publish SI.POV.DDAY step by step</li><li><a href="./indicators-admin.html">Create an indicator in NADA</a>: create an indicator and upload its data</li></ul>',60)])])}const p=e(r,[["render",s]]);export{m as __pageData,p as default};
